import pyomo.environ as pyo


DATA = {
    "nodes": [0, 1, 2, 3, 4, 5, 6],
    "source": 0,
    "sink": 6,
    # capacities[i][j] = max flow on directed arc i->j (None if no listed arc)
    "capacities": {
        0: {1: 17, 2: 3, 3: 20, 4: 11, 5: 11, 6: 3},
        1: {0: 11, 2: 12, 3: 18, 4: 5, 5: 6, 6: 4},
        2: {0: 7, 1: 2, 3: 15, 4: 13, 5: 20, 6: 18},
        3: {0: 7, 1: 4, 2: 2, 4: 2, 5: 15, 6: 3},
        4: {0: 19, 1: 12, 2: 16, 3: 4, 5: 19, 6: 4},
        5: {0: 13, 1: 20, 2: 10, 3: 14, 4: 15, 6: 1},
        6: {0: 3, 1: 3, 2: 6, 3: 20, 4: 9, 5: 10},
    },
}

# Derived helper: list of arcs with their capacity
def _arcs(d):
    arcs = {}
    for i, row in d["capacities"].items():
        for j, c in row.items():
            if i != j and c is not None:
                arcs[(i, j)] = c
    return arcs


def build_model(data=None):
    d = data or DATA
    nodes = d["nodes"]
    s = d["source"]
    t = d["sink"]
    arc_cap = _arcs(d)
    arc_list = list(arc_cap.keys())

    model = pyo.ConcreteModel()

    # Sets
    model.N = pyo.Set(initialize=nodes)
    model.A = pyo.Set(initialize=arc_list, dimen=2)

    # Variable: flow, with capacity as upper bound
    def bounds_rule(m, i, j):
        return (0.0, float(arc_cap[(i, j)]))

    model.f = pyo.Var(
        model.A,
        domain=pyo.NonNegativeReals,
        bounds=bounds_rule,
    )

    # Net flow from source to sink
    model.total = pyo.Var(domain=pyo.NonNegativeReals)

    # Incidence helper: out arcs and in arcs computed from arc set
    out_arcs = {n: [] for n in nodes}
    in_arcs = {n: [] for n in nodes}
    for (i, j) in arc_list:
        out_arcs[i].append((i, j))
        in_arcs[j].append((i, j))

    # Flow conservation: out - in = supply(node)
    def supply_rule(m, n):
        if n == s:
            return pyo.Constraint.Skip
        if n == t:
            return pyo.Constraint.Skip
        expr = sum(m.f[a] for a in out_arcs[n]) - sum(m.f[a] for a in in_arcs[n])
        return expr == 0

    model.flow_cons = pyo.Constraint(model.N, rule=supply_rule)

    # Source: net out equals total
    def source_rule(m):
        return (
            sum(m.f[a] for a in out_arcs[s]) - sum(m.f[a] for a in in_arcs[s])
            == m.total
        )

    model.source_cons = pyo.Constraint(rule=source_rule)

    # Sink: net in equals total
    def sink_rule(m):
        return (
            sum(m.f[a] for a in in_arcs[t]) - sum(m.f[a] for a in out_arcs[t])
            == m.total
        )

    model.sink_cons = pyo.Constraint(rule=sink_rule)

    # Objective: maximise data transferred from source to sink
    model.obj = pyo.Objective(expr=model.total, sense=pyo.maximize)

    return model
